    /**
 * <div id="mongodb-driver-server.executewritecommand" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Server::executeWriteCommand</h1>  <p class="verinfo">(mongodb &gt;=1.4.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Server::executeWriteCommand</span> — <span class="dc-title">Execute a database command that writes on this server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-server.executewritecommand-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Server::executeWriteCommand</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$db</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="type MongoDB\Driver\Command" style="color:#EAB766">MongoDB\Driver\Command</a></span> <span class="parameter" style="color:#3A95FF">\$command</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="type MongoDB\Driver\Cursor" style="color:#EAB766">MongoDB\Driver\Cursor</a></span></div>  <p class="simpara">   Executes the command on this server.  </p>  <p class="simpara">   This method will apply logic that is specific to commands that write (e.g.   <a href="https://www.mongodb.com/docs/manual/reference/command/drop/" class="link external">»&nbsp;drop</a>).   The default value for the <span class="literal">"writeConcern"</span> option will be   inferred from an active transaction (indicated by the   <span class="literal">"session"</span> option), followed by the   <a href="https://php.net/manual/zh/mongodb-driver-manager.construct.php#mongodb-driver-manager.construct-uri" class="link">connection URI</a>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    This method is not intended to be used to execute    <a href="https://www.mongodb.com/docs/manual/reference/command/insert/" class="link external">»&nbsp;insert</a>,    <a href="https://www.mongodb.com/docs/manual/reference/command/update/" class="link external">»&nbsp;update</a>,    or <a href="https://www.mongodb.com/docs/manual/reference/command/delete/" class="link external">»&nbsp;delete</a>    commands. Users are encouraged to use    <span class="function">{@link MongoDB\Driver\Server::executeBulkWrite()}</span> for those    operations.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-server.executewritecommand-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">db</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      The name of the database on which to execute the command.     </span>    </dd>             <dt><span class="parameter" style="color:#3A95FF">command</span> (<span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="classname">MongoDB\Driver\Command</a></span>)</dt>    <dd>     <span class="simpara">      The command to execute.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">                  <tr>          <td>session</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span></td>          <td>           <span class="simpara">            A session to associate with the operation.           </span>          </td>         </tr>                  <tr>          <td>writeConcern</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-writeconcern.php" class="classname">MongoDB\Driver\WriteConcern</a></span></td>          <td>           <span class="simpara">            A write concern to apply to the operation.           </span>          </td>         </tr>        </tbody>             </table>               <div class="warning"><strong class="warning">警告</strong>      <p class="simpara">       If you are using a <span class="literal">"session"</span> which has a transaction       in progress, you cannot specify a <span class="literal">"readConcern"</span> or       <span class="literal">"writeConcern"</span> option. This will result in an       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span>       being thrown. Instead, you should set these two options when you create       the transaction with       <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Session::startTransaction()}</span>.      </p>     </div>    </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-server.executewritecommand-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">Returns <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span> on success.</p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-server.executewritecommand-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if the <span class="literal">"session"</span> option is used with an associated transaction in combination with a <span class="literal">"readConcern"</span> or <span class="literal">"writeConcern"</span> option.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> if the <span class="literal">"session"</span> option is used in combination with an unacknowledged write concern.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors (e.g. invalid command).</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-server.executewritecommand-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.4.4</td>      <td>       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span>       will be thrown if the <span class="literal">"session"</span> option is used in       combination with an unacknowledged write concern.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 notes" id="refsect1-mongodb-driver-server.executewritecommand-notes">  <h3 class="title">注释</h3>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    It is the caller's responsibility to ensure that the server is capable    of executing the write operation. For example, executing a write operation    on a secondary (excluding its "local" database) will fail.   </span>  </p></blockquote> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-server.executewritecommand-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="classname">MongoDB\Driver\Command</a></span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Server::executeCommand()} - Execute a database command on this server</span></li>   <li><span class="function">{@link MongoDB\Driver\Server::executeReadCommand()} - Execute a database command that reads on this server</span></li>   <li><span class="function">{@link MongoDB\Driver\Server::executeReadWriteCommand()} - Execute a database command that reads and writes on this server</span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::executeWriteCommand()} - Execute a database command that writes</span></li>  </ul> </div></div>
 * 
     * Execute a database command that writes on this server
     * @link https://secure.php.net/manual/en/mongodb-driver-server.executewritecommand.php
     * @param string                  $db
     * @param \MongoDB\Driver\Command $command
     * @param array|null              $options
     * @throws InvalidArgumentException On argument parsing errors or  if the "session" option is used with an associated transaction in combination with a "readConcern" or "writeConcern" option.
     * @throws ConnectionException If connection to the server fails (for reasons other than authentication).
     * @throws AuthenticationException If authentication is needed and fails.
     * @throws RuntimeException On other errors (e.g. invalid command).
     * @since 1.4.0
     */
    final public function executeWriteCommand(string $db, Command $command, ?array $options = null): CursorInterface {}

    /**
 * <div id="mongodb-driver-server.executequery" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Server::executeQuery</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Server::executeQuery</span> — <span class="dc-title">Execute a database query on this server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-server.executequery-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Server::executeQuery</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span> <span class="parameter" style="color:#3A95FF">\$namespace</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-query.php" class="type MongoDB\Driver\Query" style="color:#EAB766">MongoDB\Driver\Query</a></span> <span class="parameter" style="color:#3A95FF">\$query</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$options</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="type MongoDB\Driver\Cursor" style="color:#EAB766">MongoDB\Driver\Cursor</a></span></div>  <p class="simpara">   Executes the query on this server.  </p>  <p class="simpara">   Default values for the <span class="literal">"readPreference"</span> option and Query's   <span class="literal">"readConcern"</span> option will be inferred from an active   transaction (indicated by the <span class="literal">"session"</span> option), followed   by the <a href="https://php.net/manual/zh/mongodb-driver-manager.construct.php#mongodb-driver-manager.construct-uri" class="link">connection URI</a>.  </p>    <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    The <span class="literal">"readPreference"</span> option does not control the server    to which the driver issues the operation; it will always be executed on    this server object. Instead, it may be used when issuing the operation to a    secondary (from a replica set connection, not standalone) or mongos node to    ensure that the driver sets the wire protocol accordingly or adds the read    preference to the operation, respectively.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-server.executequery-parameters">  <h3 class="title">参数</h3>  <dl>          <dt><span class="parameter" style="color:#3A95FF">namespace</span> (<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span>)</dt>    <dd>     <span class="simpara">      A fully qualified namespace (e.g. <span class="literal">"databaseName.collectionName"</span>).     </span>    </dd>             <dt><span class="parameter" style="color:#3A95FF">query</span> (<span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-query.php" class="classname">MongoDB\Driver\Query</a></span>)</dt>    <dd>     <span class="simpara">      The query to execute.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">options</span></dt>    <dd>     <p class="para">      </p><table class="doctable table">       <caption><strong>options</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">                  <tr>          <td>readPreference</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span></td>          <td>           <span class="simpara">            A read preference to use for selecting a server for the operation.           </span>          </td>         </tr>                  <tr>          <td>session</td>          <td><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-session.php" class="classname">MongoDB\Driver\Session</a></span></td>          <td>           <span class="simpara">            A session to associate with the operation.           </span>          </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-server.executequery-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">Returns <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span> on success.</p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-server.executequery-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-connectionexception.php" class="classname">MongoDB\Driver\Exception\ConnectionException</a></span> if connection to the server fails (for reasons other than authentication).</li><li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-authenticationexception.php" class="classname">MongoDB\Driver\Exception\AuthenticationException</a></span> if authentication is needed and fails.</li>   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-runtimeexception.php" class="classname">MongoDB\Driver\Exception\RuntimeException</a></span> on other errors (e.g. invalid query operators).</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-server.executequery-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 2.0.0</td>      <td>       The <span class="parameter" style="color:#3A95FF">options</span> parameter no longer accepts a       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span> instance.      </td>     </tr>     <tr>      <td>PECL mongodb 1.21.0</td>      <td>       Passing a <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span> object as       <span class="parameter" style="color:#3A95FF">options</span> is deprecated and will be removed in 2.0.      </td>     </tr>     <tr>      <td>PECL mongodb 1.4.0</td>      <td>       The third parameter is now an <span class="parameter" style="color:#3A95FF">options</span> array.       For backwards compatibility, this parameter will still accept a       <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span> object.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-server.executequery-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-query.php" class="classname">MongoDB\Driver\Query</a></span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-readpreference.php" class="classname">MongoDB\Driver\ReadPreference</a></span></li>   <li><span class="function">{@link MongoDB\Driver\Manager::executeQuery()} - Execute a database query</span></li>  </ul> </div></div>
 * 
     * Execute a database query on this server
     * @link https://php.net/manual/zh/mongodb-driver-server.executequery.php
     * @param string $namespace A fully qualified namespace (e.g. "databaseName.collectionName").
     * @param Query $query The MongoDB\Driver\Query to execute.
     * @param array|ReadPreference|null $options
     * @throws InvalidArgumentException on argument parsing errors.
     * @throws ConnectionException if connection to the server fails (for reasons other than authentication).
     * @throws AuthenticationException if authentication is needed and fails.
     * @throws RuntimeException on other errors (e.g. invalid command, issuing a write command to a secondary).
     * @return Cursor
     */
    final public function executeQuery(string $namespace, Query $query, array|ReadPreference|null $options = null): CursorInterface {}

    /**
 * <div id="mongodb-driver-server.gethost" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Server::getHost</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Server::getHost</span> — <span class="dc-title">Returns the hostname of this server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-server.gethost-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Server::getHost</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.string.php" class="type string" style="color:#EAB766">string</a></span></div>  <p class="simpara">   Returns the hostname of this server.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-server.gethost-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-server.gethost-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the hostname of this server.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-server.gethost-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-server.gethost-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Server::getHost()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017/"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">selectServer</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getHost</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例会输出：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">string(9)&nbsp;"localhost"</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-server.gethost-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Server::getInfo()} - Returns an array of information describing this server</span></li>   <li><span class="function">{@link MongoDB\Driver\ServerDescription::getHost()} - Returns the hostname of this server</span></li>  </ul> </div></div>
 * 
     * Returns the hostname of this server
     * @link https://php.net/manual/zh/mongodb-driver-server.gethost.php
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function getHost(): string {}

    /**
 * <div id="mongodb-driver-server.getinfo" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Server::getInfo</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Server::getInfo</span> — <span class="dc-title">Returns an array of information describing this server</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-server.getinfo-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Server::getInfo</strong></span>(): <span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></div>  <p class="simpara">   Returns an array of information describing the server. This array is derived   from the most recent   <a href="https://www.mongodb.com/docs/manual/reference/command/hello/" class="link external">»&nbsp;hello</a>   command response obtained through   <a href="https://github.com/mongodb/specifications/blob/master/source/server-discovery-and-monitoring/server-discovery-and-monitoring.md" class="link external">»&nbsp;server monitoring</a>.  </p>  <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:    <span class="simpara">    When the driver is connected to a load balancer, this method will return    the backing server's    <a href="https://www.mongodb.com/docs/manual/reference/command/hello/" class="link external">»&nbsp;hello</a>    command response from the initial connection handshake. This is in contrast    to other methods (e.g. <span class="function">{@link MongoDB\Driver\Server::getType()}</span>),    which will return information about the load balancer itself.   </span>  </p></blockquote> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-server.getinfo-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-server.getinfo-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns an array of information describing this server.  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-server.getinfo-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-server.getinfo-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Server::getInfo()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">'mongodb://localhost:27017/'</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$rp </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\ReadPreference</span><span style="color: #007700">(</span><span style="color: #DD0000">'primary'</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">selectServer</span><span style="color: #007700">(</span><span style="color: #9876AA">\$rp</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getInfo</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(23)&nbsp;{<br>&nbsp;&nbsp;["helloOk"]=&gt;<br>&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;["topologyVersion"]=&gt;<br>&nbsp;&nbsp;array(2)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["processId"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#4&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;string(24)&nbsp;"617b6d696a3a89d2f77e6df0"<br>&nbsp;&nbsp;&nbsp;&nbsp;}<br>&nbsp;&nbsp;&nbsp;&nbsp;["counter"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(6)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["hosts"]=&gt;<br>&nbsp;&nbsp;array(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(15)&nbsp;"localhost:27017"<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["setName"]=&gt;<br>&nbsp;&nbsp;string(3)&nbsp;"rs0"<br>&nbsp;&nbsp;["setVersion"]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;["ismaster"]=&gt;<br>&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;["secondary"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["primary"]=&gt;<br>&nbsp;&nbsp;string(15)&nbsp;"localhost:27017"<br>&nbsp;&nbsp;["me"]=&gt;<br>&nbsp;&nbsp;string(15)&nbsp;"localhost:27017"<br>&nbsp;&nbsp;["electionId"]=&gt;<br>&nbsp;&nbsp;object(MongoDB\BSON\ObjectId)#5&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["oid"]=&gt;<br>&nbsp;&nbsp;&nbsp;&