    /**
 * <div id="mongodb-driver-server.getlatency" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Server::getLatency</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Server::getLatency</span> — <span class="dc-title">Returns the latency of this server in milliseconds</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-server.getlatency-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Server::getLatency</strong></span>(): <span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type integer" style="color:#EAB766">integer</a></span></span></div>  <p class="simpara">   Returns the latency of this server in milliseconds. This is the client's   measured   <a href="https://github.com/mongodb/specifications/blob/master/source/server-discovery-and-monitoring/server-discovery-and-monitoring.md#round-trip-time" class="link external">»&nbsp;round trip time</a>   of a <span class="literal">hello</span> command.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-server.getlatency-parameters">  <h3 class="title">参数</h3>  <p class="simpara">此函数没有参数。</p> </div> <div class="refsect1 returnvalues" id="refsect1-mongodb-driver-server.getlatency-returnvalues">  <h3 class="title">返回值</h3>  <p class="simpara">   Returns the latency of this server in milliseconds, or <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no latency   has been measured (e.g. client is connected to a load balancer).  </p> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-server.getlatency-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-server.getlatency-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.11.0</td>      <td>       This method will return <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong> if no latency has been measured. In       earlier versions, an integer was always returned and an unset value       might be reported as <span class="literal">-1</span>.      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-server.getlatency-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-1">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Server::getLatency()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017/"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$server </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">selectServer</span><span style="color: #007700">();<br><br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$server</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getLatency</span><span style="color: #007700">());<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">int(592)</blockquote></div>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-server.getlatency-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="function">{@link MongoDB\Driver\Server::getInfo()} - Returns an array of information describing this server</span></li>   <li><span class="function">{@link MongoDB\Driver\ServerDescription::getRoundTripTime()} - Returns the server's round trip time in milliseconds</span></li>   <li><a href="https://github.com/mongodb/specifications/blob/master/source/server-discovery-and-monitoring/server-discovery-and-monitoring.md" class="link external">»&nbsp;Server Discovery and Monitoring Specification</a></li>  </ul> </div></div>
 * 
     * Returns the latency of this server
     * @link https://php.net/manual/zh/mongodb-driver-server.getlatency.php
     * @throws InvalidArgumentException on argument parsing errors.
     */
    final public function getLatency(): int {}

